const F_BODEC = (() => {
  const X = w => 60 + (Math.log10(w) + 2) * 100, a = 6, tau = 1, w1 = 1 / (a * tau), w2 = 1 / tau, G = w => 20 * Math.log10(Math.hypot(1, a * tau * w) / Math.hypot(1, tau * w)), Ph = w => (Math.atan(a * tau * w) - Math.atan(tau * w)) * 180 / Math.PI;
  const YG = g => 120 - g * 4.2, YP = p => 300 - p * 1.6;
  const ws = [...Array(121)].map((_, i) => 10 ** (-2 + i * 0.033));
  const cg = ws.map(w => `${X(w).toFixed(1)},${YG(G(w)).toFixed(1)}`).join(" "), cp = ws.map(w => `${X(w).toFixed(1)},${YP(Ph(w)).toFixed(1)}`).join(" ");
  const wm = 1 / (tau * Math.sqrt(a));
  return fig(520, 340, "Diagramme de Bode du correcteur à avance de phase",
    `<line class="ax" x1="60" y1="120" x2="500" y2="120"/><line class="ax" x1="60" y1="20" x2="60" y2="130"/><line class="ax" x1="60" y1="300" x2="500" y2="300"/><line class="ax" x1="60" y1="190" x2="60" y2="306"/>` +
    T(66, 30, "gain (dB)", "sm", 11) + T(66, 200, "phase (°)", "sm", 11) + T(470, 140, "ω", "sm", 12) + T(470, 318, "ω", "sm", 12) +
    `<line class="vr" x1="60" y1="${YG(0) - 0}" x2="${X(w1)}" y2="${YG(0)}"/><line class="vr" x1="${X(w1)}" y1="${YG(0)}" x2="${X(w2)}" y2="${YG(20 * Math.log10(a))}"/><line class="vr" x1="${X(w2)}" y1="${YG(20 * Math.log10(a))}" x2="500" y2="${YG(20 * Math.log10(a))}"/>` +
    `<polyline class="k" points="${cg}"/>` +
    `<line class="vr" x1="60" y1="${YP(0)}" x2="${X(w1)}" y2="${YP(0)}"/><line class="vr" x1="${X(w1)}" y1="${YP(0)}" x2="${X(w1)}" y2="${YP(90)}"/><line class="vr" x1="${X(w1)}" y1="${YP(90)}" x2="${X(w2)}" y2="${YP(90)}"/><line class="vr" x1="${X(w2)}" y1="${YP(90)}" x2="${X(w2)}" y2="${YP(0)}"/><line class="vr" x1="${X(w2)}" y1="${YP(0)}" x2="500" y2="${YP(0)}"/>` +
    `<polyline class="k" points="${cp}"/>` +
    [[w1, "1/(aτ)"], [wm, "ωmax"], [w2, "1/τ"]].map(([w, s]) => `<line class="thin" x1="${X(w)}" y1="20" x2="${X(w)}" y2="300"/>` + Tc(X(w), 334, s, "", 12)).join("") +
    T(66, YG(0) - 6, "20 log C₂", "", 11) + T(392, YG(20 * Math.log10(a)) - 8, "20 log(a C₂)", "", 11) + T(X(wm) + 6, YG(10 * Math.log10(a)) + 20, "20 log C₂ + 10 log a", "b", 11) + T(X(w1) + 4, YG(8) - 4, "+20 dB/déc", "r", 11) +
    T(X(wm) + 8, YP(Ph(wm)) - 6, "φmax", "b", 12) + T(40, YP(0) + 4, "0", "", 11) + T(36, YP(90) + 4, "90", "", 11),
    "En rouge, les asymptotes ; en noir, l'allure réelle. Le gain est décalé de $20\\log C_2$ ; la phase culmine en $\\omega_{\\max} = \\frac1{\\tau\\sqrt a}$, milieu (en échelle log) de $\\frac1{a\\tau}$ et $\\frac1\\tau$.");
})();

