LEMME.rappels({
  "si24-trd": { t: "Principe fondamental de la dynamique", b: R`<p>Pour un système $E$ en mouvement par rapport à un repère galiléen $R_0$ :</p><div class="sbox">$$M\,\vec a(G,E/R_0) = \vec R(\bar E\to E)\qquad\text{(théorème de la résultante dynamique)}.$$</div><p>On isole, on fait le bilan des actions extérieures, puis on projette sur des axes bien choisis.</p>` },
  "si24-coulomb": { t: "Lois de Coulomb (glissement)", b: R`<p>Au contact en $I$, s'il y a glissement de vitesse $\vec V_g$ :</p><div class="sbox">$$\|\vec T\| = f\,\|\vec N\|,\qquad\vec T\ \text{colinéaire à}\ \vec V_g\ \text{et de sens opposé}.$$</div>` },
  "si24-tec": { t: "Théorème de l'énergie cinétique", b: R`<p>Pour un ensemble $E$ de solides, dans $R_0$ galiléen :</p><div class="sbox">$$\frac{d}{dt}E_c(E/R_0) = P(\bar E\to E/R_0)+P_{\text{int}}(E).$$</div><p>Puissance d'une action $\{\vec R\,;\,\vec M_A\}$ sur un solide $S$ : $P = \vec R\cdot\vec V(A,S/R_0)+\vec M_A\cdot\vec\Omega(S/R_0)$. Liaison parfaite : puissance intérieure nulle. Forme intégrée : $\Delta E_c = W_{\text{ext}}+W_{\text{int}}$.</p>` },
  "si24-euler": { t: "Schéma d'Euler explicite", b: R`<p>Pour $\frac{dv}{dt} = F(v)$ et un pas $h$ :</p><div class="sbox">$$v_{i+1} = v_i+h\,F(v_i).$$</div><p>On approche la dérivée par $\frac{v_{i+1}-v_i}h$ en évaluant la pente au point <b>connu</b> $v_i$.</p>` },
  "si24-fermeture": { t: "Fermeture géométrique", b: R`$$\overrightarrow{O_1O_2}+\overrightarrow{O_2O_3}+\dots+\overrightarrow{O_nO_1} = \vec0.$$<p>Projeter sur deux axes, éliminer l'angle inutile par $\cos^2+\sin^2 = 1$.</p>` },
  "si24-helico": { t: "Liaison hélicoïdale", b: R`<p>Vis de pas $p$ (en mètre par tour) : un tour de rotation relative donne une translation de $p$. Donc</p><div class="sbox">$$V = \frac{p}{2\pi}\,\omega\qquad(\omega\ \text{en rad/s}).$$</div>` },
  "si24-ec": { t: "Énergie cinétique d'un solide", b: R`$$\begin{aligned}\text{rotation autour de }\Delta&:\ E_c = \tfrac12J_\Delta\omega^2\\\text{translation}&:\ E_c = \tfrac12Mv^2\\\text{général}&:\ E_c = \tfrac12MV(G)^2+\tfrac12\,\vec\Omega\cdot\overline{\overline I}(G)\,\vec\Omega\end{aligned}\qquad E_c = \tfrac12J_{eq}\,\omega^2.$$` },
  "si24-inertie": { t: "Forme des matrices d'inertie", b: R`<ul><li>Un plan de symétrie matérielle $(O,\vec x,\vec y)$ annule les produits d'inertie contenant $z$ : $D = E = 0$.</li><li>Deux plans de symétrie orthogonaux : matrice <b>diagonale</b>.</li><li>Solide de révolution d'axe $(O,\vec x)$ : diagonale, $B = C$, dans toute base contenant $\vec x$.</li></ul>` },
  "si24-laplace": { t: "Transformée de Laplace", b: R`<p>Conditions de Heaviside (conditions initiales nulles) : $\frac{df}{dt}\to pF(p)$ et $\int f\to\frac{F(p)}p$.</p><div class="sbox">$$\text{Valeur finale : }\lim_{t\to+\infty}f(t) = \lim_{p\to0}pF(p).$$</div><p>Échelon d'amplitude $A$ : $\frac Ap$ ; rampe de pente $a$ : $\frac a{p^2}$.</p>` },
  "si24-boucle": { t: "Boucle fermée (formule de Black)", b: R`<p>Chaîne directe $H(p)$, retour $K(p)$, comparateur $+/-$ :</p><div class="sbox">$$\frac{S}{E} = \frac{H}{1+HK},\qquad\text{FTBO} = H\,K.$$</div>` },
  "si24-ordre1": { t: "Système du premier ordre", b: R`<p>$H(p) = \frac{K}{1+\tau p}$ : réponse à un échelon sans dépassement, tangente à l'origine non nulle, valeur finale $K$ fois l'échelon.</p><div class="sbox">$$t_{5\%} = 3\tau.$$</div>` },
  "si24-avance": { t: "Correcteur à avance de phase", b: R`<p>$C(p) = C_2\frac{1+a\tau p}{1+\tau p}$ avec $a>1$. Il ajoute de la phase entre $\frac1{a\tau}$ et $\frac1\tau$.</p><div class="sbox">$$\omega_{\max} = \frac1{\tau\sqrt a},\qquad\sin\varphi_{\max} = \frac{a-1}{a+1},\qquad|C(j\omega_{\max})| = C_2\sqrt a.$$</div><p>On place $\omega_{\max}$ là où l'on veut la marge (la pulsation de coupure à 0 dB visée).</p>` },
  "si24-marge": { t: "Marge de phase", b: R`<p>À la pulsation $\omega_{0\,\mathrm{dB}}$ où le gain de la FTBO vaut $0\ \mathrm{dB}$ :</p><div class="sbox">$$M_\varphi = 180^\circ+\arg\text{FTBO}(j\omega_{0\,\mathrm{dB}}).$$</div>` }
});

